/* Workbench views and interactions. Works directly from index.html or a local server. */
const C=Hwadam, KEY='hwadam-prototype-v1';
let storageWarning=false,state;try{state=JSON.parse(localStorage.getItem(KEY))||C.seed()}catch{state=C.seed();storageWarning=true}
let currentFilter='all',search='',selectedNode=-1,detailTab='graph',busy=false,runMessage='',runError='',upload=null,seriesFilter='all',appTimer=null,appGeneration=0;
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',graph:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><path d="M6 9v6M9 6h9v9"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5.8l10 5.4"/>',entity:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',operation:'<path d="m8 5-6 7 6 7M16 5l6 7-6 7M14 3l-4 18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',sliders:'<path d="M4 7h7m4 0h5M4 17h3m4 0h9"/><circle cx="13" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',wave:'<path d="M2 12c4-15 6 15 10 0s6 15 10 0"/>',play:'<path d="m8 4 12 8-12 8z"/>',check:'<path d="m5 12 4 4L19 6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="9" cy="18" r="2" fill="currentColor"/>',link:'<path d="m10 14 4-4M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0M16 8l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 2 5-7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('ko-KR');const date=x=>new Date(x).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'});const time=x=>new Date(x).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
const art=id=>state.artifacts.find(x=>x.id===id),comp=id=>state.compositions.find(x=>x.id===id),app=id=>state.apps.find(x=>x.id===id);
const route=()=>{const [page='apps',id]=location.hash.slice(1).split('/');return {page:page||'apps',id}};
const btn=(label,action,ic='',primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;
const badge=(text,color='')=>`<span class="badge ${color}">${text}</span>`;
const modelName=m=>m==='seasonal'?'주간 반복 기준':'직전 값 유지';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageWarning=true;toast('저장 공간이 부족합니다. 현재 작업은 이 화면에만 유지됩니다.')}}
let toastTimer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function go(path){location.hash=path}
function searchbar(){return `<label class="search">${icon('search')}<input id="search" aria-label="목록 검색" placeholder="이름으로 검색…" value="${esc(search)}"></label>`}
function head(eyebrow,title,desc,actions=''){return `<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p class="page-description">${esc(desc)}</p></div><div class="actions">${actions}</div></header>`}
function empty(title,desc,action=''){return `<div class="empty"><h3>${title}</h3><p>${desc}</p>${action}</div>`}
const names={apps:'앱',compositions:'컴포지션',artifacts:'아티팩트',entities:'엔티티',operations:'오퍼레이션',runs:'실행 이력'};
function shell(content){const r=route();const nav=(p,ic,count)=>`<a class="nav-link ${r.page===p?'active':''}" href="#${p}" aria-label="${names[p]}" ${r.page===p?'aria-current="page"':''}>${icon(ic)}<span>${names[p]}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</a>`;document.querySelector('#root').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#apps" aria-label="화담 홈"><span class="brand-mark">✳</span><span>hwadam<span style="color:#8c74c9">.</span></span></a><div class="workspace"><div class="workspace-icon">S</div><div><strong>성수 리테일 랩</strong><small>Personal workspace</small></div></div><div class="nav-label">WORKSPACE</div><nav aria-label="주 메뉴">${nav('apps','grid',state.apps.length)}${nav('compositions','graph',state.compositions.length)}${nav('artifacts','box',state.artifacts.length)}<div class="nav-label">BUILDING BLOCKS</div>${nav('entities','entity')}${nav('operations','operation')}<div class="nav-label">ACTIVITY</div>${nav('runs','clock')}</nav><div class="side-bottom"><button class="nav-link" data-action="guide">${icon('help')}<span>프로토타입 가이드</span></button><div class="local"><span class="dot"></span>이 브라우저에 저장됨</div><div class="profile"><span class="avatar">H</span><div><strong>나의 워크스페이스</strong><small>Local · Personal</small></div></div></div></aside><div class="main-wrap"><div class="topbar"><div class="crumb"><span>워크스페이스</span><span>/</span><a href="#${r.page}">${names[r.page]||'앱'}</a>${r.id?'<span>/</span><span>상세</span>':''}</div><div class="top-tools"><span class="prototype">INTERACTIVE PROTOTYPE</span><button data-action="guide" aria-label="사용 가이드">${icon('help')}</button></div></div><main id="main" tabindex="-1" class="content fade-in">${storageWarning?'<div class="info-strip">브라우저 저장소를 사용할 수 없어 변경 내용이 새로고침 후 유지되지 않을 수 있습니다.</div>':''}${content}</main></div></div>`;bindPage()}
function miniChart(){return `<svg class="mini-chart" viewBox="0 0 260 65" preserveAspectRatio="none"><path d="M0 20H260M0 40H260M0 60H260" stroke="#efedf4" fill="none"/><path d="M0 53 10 49 20 53 30 35 40 42 50 40 60 47 70 31 80 34 90 17 100 28 110 24 120 30 130 10 140 21 150 18 160 24 170 11 180 17" stroke="#b2a4c7" stroke-width="1.7" fill="none"/><path d="M180 17 190 8 200 17 210 14 220 20 230 7 240 12 250 7 260 13" stroke="#7b5bc2" stroke-width="2" stroke-dasharray="4 3" fill="none"/><path d="M180 0V65" stroke="#ddd5eb" stroke-dasharray="3 3"/></svg>`}
function appCard(a){const output=art(a.artifact),sum=output?.rows.reduce((v,r)=>v+r.forecast_value,0)||0;return `<a class="card" href="#apps/${a.id}"><div class="app-preview"><div class="mini-app"><div class="mini-title"><span>${esc(a.name)}</span><span style="color:#847692">● LIVE</span></div><div class="mini-metrics"><span>예상 총수요<b>${fmt(sum)}</b></span><span>예측 기간<b>${a.params.horizon}<small style="font-size:8px">일</small></b></span><span>시계열<b>${new Set(output?.rows.map(r=>r.series_id)).size}</b></span></div>${miniChart()}</div></div><div class="card-body"><div class="card-top"><span class="badge purple">DASHBOARD</span>${badge('● 사용 가능','green')}</div><h3>${esc(a.name)}</h3><p>${esc(a.desc)}</p><div class="card-foot"><span>${iconInline('graph')} ${esc(comp(a.comp)?.name)}</span><span>열기 ↗</span></div></div></a>`}
const iconInline=n=>`<span style="display:inline-flex;vertical-align:middle">${icon(n)}</span>`;
function appsPage(){const items=state.apps.filter(x=>x.name.includes(search));return head('YOUR WORK, ALIVE','앱','데이터와 조합이, 직접 사용할 수 있는 도구가 되는 곳.',btn('새 앱 만들기','new-app','plus',true))+`<div class="intro"><div><h2>만들어 둔 능력으로, 다음 일을 시작하세요.</h2><p>아티팩트를 연결하고, 컴포지션으로 실행하고, 앱에서 결과를 탐색하세요.<br>각각의 결과에는 그 결과를 만든 과정이 함께 남습니다.</p></div><div class="flow-strip"><span class="flow-step">${icon('box')}아티팩트</span>→<span class="flow-step">${icon('graph')}컴포지션</span>→<span class="flow-step">${icon('grid')}앱</span></div></div><div class="toolbar"><h2 class="section-title">내 앱 <span class="muted">${state.apps.length}</span></h2>${searchbar()}</div><div class="cards">${items.map(appCard).join('')}${!search?`<button class="new-card" data-action="new-app"><span class="plus-circle">+</span><strong>새로운 도구를 만들어 보세요</strong><small>예측 결과로 대시보드 만들기</small></button>`:''}</div>${!items.length&&search?empty('검색 결과가 없습니다','다른 이름으로 검색해 주세요.'):''}<div class="section-bar"><h2 class="section-title">최근 작업</h2><a class="btn text" href="#runs">실행 이력 보기 →</a></div><div class="panel">${state.runs.slice(0,3).map(r=>`<a class="recent-row row-link" href="#runs/${r.id}"><span class="tile-icon green">${icon('check')}</span><div><strong>${esc(comp(r.comp)?.name)} 실행 완료</strong><small>${modelName(r.params.model)} · ${r.params.horizon}일 예측 · 결과 아티팩트 생성</small></div><div class="right">${badge('완료','green')}<span class="muted">${date(r.created)} ${time(r.created)}</span>${icon('chevron')}</div></a>`).join('')}</div><div class="bottom-note"><span class="dot"></span>샘플 워크스페이스 · 가상 판매 데이터 · 외부 서버로 전송하지 않습니다</div>`}
function compCard(c){return `<a class="card" href="#compositions/${c.id}"><div class="graph-mini">${['entity',...c.nodes.map(id=>C.operations.find(o=>o.id===id)?.icon),'box'].map((ic,i)=>(i?'<i></i>':'')+`<span class="mini-node">${icon(ic)}</span>`).join('')}</div><div class="card-body"><div class="card-top">${badge('COMPOSITION','purple')}${badge(c.dirty?'수정 중':c.published?`v${c.version} · 발행됨`:'초안',c.published&&!c.dirty?'green':'orange')}</div><h3>${esc(c.name)}</h3><p>${esc(c.desc)}</p><div class="card-foot"><span>${c.nodes.length+2}개 노드 · ${state.runs.filter(r=>r.comp===c.id).length}회 실행</span><span>그래프 열기 ↗</span></div></div></a>`}
function compsPage(){const all=state.compositions.filter(x=>x.name.includes(search)&&(currentFilter==='all'||(currentFilter==='published'?x.published:!x.published)));return head('REUSABLE WORKFLOWS','컴포지션','엔티티와 오퍼레이션을 연결해, 다시 쓸 수 있는 작업 방법을 만드세요.',btn('컴포지션 만들기','new-comp','plus',true))+`<div class="toolbar">${filters([['all','전체'],['published','발행됨'],['draft','초안']])}${searchbar()}</div><div class="cards">${all.map(compCard).join('')}<button class="new-card" style="min-height:275px" data-action="new-comp"><span class="plus-circle">+</span><strong>새 컴포지션</strong><small>작은 기능을 연결해, 하나의 흐름으로</small></button></div>`}
function filters(items){return `<div class="tabs" role="group" aria-label="종류 필터">${items.map(([id,label])=>`<button class="tab ${currentFilter===id?'active':''}" data-filter="${id}" aria-pressed="${currentFilter===id}">${label}</button>`).join('')}</div>`}
const kindNames={input:'입력 데이터',output:'예측 결과',composition:'컴포지션 설계'};
function artifactCard(a){return `<a class="card artifact-card" href="#artifacts/${a.id}"><div class="card-body"><div class="card-top"><span class="tile-icon ${a.kind==='input'?'green':a.kind==='composition'?'orange':''}">${icon(a.kind==='composition'?'graph':'file')}</span>${badge(a.kind==='composition'?'JSON':'CSV')}</div><h3 class="file-name">${esc(a.name)}</h3><p>${kindNames[a.kind]}${a.rows?` · ${fmt(a.rows.length)}행 · ${Object.keys(a.rows[0]||{}).length}개 열`:` · 설계 v${a.snapshot.version}`}<br>${a.kind==='output'?`${a.params.horizon}일 예측 · ${modelName(a.params.model)}`:a.kind==='input'?'시계열 매핑 완료 · 일 단위':'노드·연결·파라미터 스냅샷'}</p><div class="card-foot"><span>${date(a.created)} 등록</span><span>상세 보기 ↗</span></div></div></a>`}
function artifactsPage(){let items=state.artifacts.filter(a=>a.name.includes(search)&&(currentFilter==='all'||a.kind===currentFilter));return head('A TRACE OF EVERY RESULT','아티팩트','원본 데이터부터 실행 결과까지, 작업에 쓰인 파일을 한곳에서 관리하세요.',btn('CSV 업로드','upload','upload',true))+`<div class="dropzone" id="dropzone"><span class="tile-icon">${icon('upload')}</span><div><strong>CSV를 놓으면, 새로운 아티팩트가 됩니다.</strong><p>열을 매핑하고 데이터셋 엔티티로 연결하세요. 최대 2MB · 10,000행</p></div><div class="actions">${btn('샘플 CSV 받기','sample-download','download')}</div></div><div class="toolbar">${filters([['all','전체'],['input','입력 데이터'],['output','예측 결과'],['composition','컴포지션 설계']])}${searchbar()}</div><div class="cards">${items.map(artifactCard).join('')}</div>${items.length?'':empty('아티팩트가 없습니다','CSV를 업로드하거나 컴포지션을 실행해 보세요.',btn('CSV 업로드','upload','upload'))}`}
function table(rows,limit=30){if(!rows?.length)return empty('데이터가 없습니다','');const keys=Object.keys(rows[0]);return `<div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length>limit?`<div class="help" style="padding:12px 20px">전체 ${fmt(rows.length)}행 중 처음 ${limit}행 · 전체 데이터는 파일로 내려받을 수 있습니다.</div>`:''}`}
function artifactDetail(a){return head('ARTIFACT / '+a.kind.toUpperCase(),a.name,kindNames[a.kind]+' · '+date(a.created)+' '+time(a.created)+' 등록',btn('다운로드','download','download',false,`data-id="${a.id}"`)+(a.kind==='output'?btn('앱 만들기','new-app','plus',true,`data-artifact="${a.id}"`):a.kind==='input'?btn('컴포지션 만들기','new-comp','graph',true,`data-input="${a.id}"`):''))+`${a.kind==='output'?lineage(a):''}<div class="detail-grid"><section class="panel"><div class="panel-title"><h2>${a.kind==='composition'?'설계 스냅샷':'데이터 미리보기'}</h2>${badge(a.rows?fmt(a.rows.length)+'행':'JSON')}</div>${a.snapshot?`<pre>${esc(JSON.stringify(a.snapshot,null,2))}</pre>`:table(a.rows)}</section><aside class="panel panel-pad"><h2 class="section-title">아티팩트 정보</h2><dl class="metadata"><div><dt>아티팩트 ID</dt><dd>${esc(a.id)}</dd></div><div><dt>유형</dt><dd>${kindNames[a.kind]}</dd></div>${a.comp?`<div><dt>컴포지션</dt><dd><a href="#compositions/${a.comp}">${esc(comp(a.comp)?.name)} ↗</a></dd></div>`:''}${a.run?`<div><dt>실행 근거</dt><dd><a href="#runs/${a.run}">${a.run} ↗</a></dd></div>`:''}${a.params?`<div><dt>모델 / 예측 기간</dt><dd>${modelName(a.params.model)} / ${a.params.horizon}일</dd></div>`:''}${a.mapping?`<div><dt>열 매핑</dt><dd>날짜 ← ${esc(a.mapping.timestamp)}<br>시계열 ← ${esc(a.mapping.series)}<br>수량 ← ${esc(a.mapping.value)}</dd></div>`:''}<div><dt>연결된 엔티티</dt><dd>${state.entities.filter(e=>e.artifacts.includes(a.id)).map(e=>`<a href="#entities/${e.id}">${esc(e.name)} ↗</a>`).join('<br>')||'설계 자산'}</dd></div></dl><div class="divider"></div><p class="help">등록된 파일은 이 시점의 데이터입니다. 다시 실행하면 기존 결과를 보존하고 새 아티팩트를 만듭니다.</p></aside></div>`}
function lineage(a){return `<div class="eyebrow">DATA LINEAGE</div><div class="lineage"><a href="#artifacts/${a.input}">${iconInline('file')} 입력 CSV</a><span>→</span><a href="#compositions/${a.comp}">${esc(comp(a.comp)?.name)}</a><span>→</span><a href="#runs/${a.run}">${esc(a.run)}</a><span>→</span><span class="step">예측 결과</span></div>`}
function options(items,current){return items.map(([id,label])=>`<option value="${esc(id)}" ${String(current)===String(id)?'selected':''}>${esc(label)}</option>`).join('')}
function field(label,name,value,type='text'){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" required maxlength="80"></div>`}
function selectField(label,name,items,current,extra=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${options(items,current)}</select></div>`}
function parameterFields(p,attr='data-param'){return selectField('예측 기간','horizon',[[7,'7일'],[14,'14일'],[28,'28일']],p.horizon,attr)+selectField('예측 모델','model',[['seasonal','주간 반복 기준'],['last','직전 값 유지']],p.model,attr)+selectField('학습 데이터 범위','range',[['all','전체 기간'],['28','최근 28일'],['56','최근 56일']],p.range,attr)}
function node(c,i){const isEntity=i===-1||i===c.nodes.length;let op=isEntity?null:C.operations.find(o=>o.id===c.nodes[i]);const title=i===-1?state.entities.find(e=>e.artifacts.includes(c.input))?.name||'입력 데이터셋':i===c.nodes.length?'수요 예측 결과':op.name;return `<button class="graph-node ${selectedNode===i?'active':''} ${isEntity?'entity':''}" data-node="${i}">${i!==-1?'<i class="port in"></i>':''}<span class="tile-icon ${isEntity?'green':''}">${icon(isEntity?'entity':op.icon)}</span><span><small>${isEntity?'ENTITY':`OPERATION · ${String(i+1).padStart(2,'0')}`}</small><strong>${esc(title)}</strong></span>${i!==c.nodes.length?'<i class="port out"></i>':''}</button>`}
function inspector(c){if(selectedNode===-1)return `<h3>입력 엔티티</h3><p class="help">실행에 사용할 CSV 아티팩트를 선택하세요.</p>${selectField('연결된 입력','comp-input',state.artifacts.filter(a=>a.kind==='input').map(a=>[a.id,a.name]),c.input)}<a class="btn text" href="#artifacts/${c.input}">원본 데이터 보기 ↗</a><div class="divider"></div><h3>실행 설정</h3>${parameterFields(c.params)}<p class="help">실행할 때 입력과 설정을 고정해 이력에 남깁니다.</p>`;
 if(selectedNode===c.nodes.length)return `<h3>수요 예측 결과</h3><p class="help">ForecastTable 유형의 결과 엔티티입니다. 실행마다 생성된 CSV 아티팩트를 참조합니다.</p><div class="port-contract">입력 <b>CSV</b></div><div class="divider"></div>${state.runs.filter(r=>r.comp===c.id).slice(0,3).map(r=>`<a class="btn text" href="#artifacts/${r.output}">${date(r.created)} 결과 보기 ↗</a><br>`).join('')}`;
 const op=C.operations.find(o=>o.id===c.nodes[selectedNode]);if(!op){selectedNode=-1;return inspector(c)}return `<div class="inspect-node-title"><span class="tile-icon">${icon(op.icon)}</span><div><h3>${op.name}</h3><span class="help">노드 ${selectedNode+1} · v1.0</span></div></div><p class="help">${op.desc}</p><div class="port-contract">입력 <b>${op.input}</b></div><div class="port-contract">출력 <b>${op.output}</b></div>${op.id==='forecast'?parameterFields(c.params):''}${op.id==='smooth'?'<p class="help">각 날짜까지 최대 7개 관측값의 평균을 계산합니다.</p>':''}<div class="divider"></div><a class="btn text" href="#operations/${op.id}">오퍼레이션 정의 보기 ↗</a><div class="actions" style="margin-top:20px">${btn('위로','node-up','',false,selectedNode===0?'disabled':'')}${btn('아래로','node-down','',false,selectedNode===c.nodes.length-1?'disabled':'')}${btn('노드 제거','node-remove')}</div><p class="help">순서를 바꾸면 인접 노드의 포트가 다시 연결됩니다. 실행 전 연결 형식을 검증합니다.</p>`}
function compDetail(c){const runs=state.runs.filter(r=>r.comp===c.id);return head('COMPOSITION / WORKFLOW',c.name,c.desc,btn('이름 수정','edit-comp')+btn('노드 추가','add-node','plus')+btn('발행','publish','check')+btn(busy?'실행 중…':'실행','run','play',true,busy?'disabled':''))+`<div class="toolbar" style="margin-bottom:8px"><div class="actions">${badge(c.dirty?'수정 중 · 미발행 변경 있음':c.published?`v${c.version} 발행됨`:'초안',c.dirty?'orange':'green')}<span class="muted">${c.nodes.length+2}개 노드 · ${c.nodes.length+1}개 연결</span></div><span class="help">노드를 선택해 설정과 연결을 확인하세요</span></div><div class="tabs">${[['graph','그래프'],['runs',`실행 이력 ${runs.length}`],['details','메타데이터']].map(([id,t])=>`<button class="tab ${detailTab===id?'active':''}" data-detail-tab="${id}">${t}</button>`).join('')}</div>${runError?`<div class="run-status error" role="alert">${esc(runError)}</div>`:''}${busy?'<div class="run-status running"><span class="spinner"></span>입력 검증 → 시계열 변환 → 수요 예측 → 결과 등록 중…</div>':runMessage?`<div class="run-status">${icon('check')}실행 완료 · 새 예측 결과가 등록되었습니다.<div class="actions"><a class="btn" href="#artifacts/${runMessage}">결과 보기 →</a>${btn('앱 만들기','new-app','plus',false,`data-artifact="${runMessage}"`)}</div></div>`:''}${detailTab==='graph'?`<div class="editor-layout"><div class="canvas"><div class="canvas-label"><span>COMPOSITION CANVAS</span><span>자동 연결 · 세로 흐름</span></div><div class="graph">${node(c,-1)}${c.nodes.map((id,i)=>`<div class="connector"><span>${C.operations.find(o=>o.id===id).input}</span></div>${node(c,i)}`).join('')}<div class="connector"><span>CSV</span></div>${node(c,c.nodes.length)}</div></div><aside class="inspector">${inspector(c)}</aside></div>`:detailTab==='runs'?runsTable(runs):`<div class="panel panel-pad">${field('이름','meta-name',c.name)}<dl class="metadata"><div><dt>ID</dt><dd>${c.id}</dd></div><div><dt>버전</dt><dd>v${c.version} · ${c.dirty?'초안 변경 있음':'발행 스냅샷 유지'}</dd></div><div><dt>출력 계약</dt><dd>ForecastTable → CSV</dd></div></dl><p class="help">발행 시 컴포지션 설계 스냅샷이 JSON 아티팩트로 함께 등록됩니다.</p>${btn('이름 저장','save-meta','check')}</div>`}`}
function chart(history,output){let combined=[...history.map(r=>r.timestamp),...output.map(r=>r.forecast_timestamp)];const dates=[...new Set(combined)].sort(),histDates=[...new Set(history.map(r=>r.timestamp))].sort();const actual=dates.map(d=>history.filter(r=>r.timestamp===d).reduce((v,r)=>v+r.value,0)),pred=dates.map(d=>output.filter(r=>r.forecast_timestamp===d).reduce((v,r)=>v+r.forecast_value,0));const max=Math.max(...actual,...pred,1)*1.18,W=880,H=240,x=i=>50+i*(W-75)/Math.max(dates.length-1,1),y=v=>H-30-v*(H-52)/max;const hi=histDates.length-1;const hp=actual.slice(0,hi+1).map((v,i)=>`${x(i)},${y(v)}`).join(' '),pp=[`${x(hi)},${y(actual[hi])}`,...pred.slice(hi+1).map((v,j)=>`${x(hi+1+j)},${y(v)}`)].join(' ');return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${histDates.length}일 실제 판매와 ${dates.length-histDates.length}일 예측 수요의 추이"><rect x="${x(hi)}" y="13" width="${W-25-x(hi)}" height="197" fill="#f6f2fc"/>${Array.from({length:5},(_,i)=>{let v=max*i/4;return `<path d="M50 ${y(v)}H855" stroke="#ececf2" stroke-dasharray="3 4"/><text x="39" y="${y(v)+3}" text-anchor="end" fill="#727080" font-size="9">${fmt(Math.round(v))}</text>`}).join('')}<path d="M${x(hi)} 13V210" stroke="#c9badd" stroke-dasharray="4 4"/><text x="${x(hi)+10}" y="27" fill="#8e72b9" font-size="9">예측 시작</text><polyline points="${hp}" fill="none" stroke="#b2a6c6" stroke-width="2.3" stroke-linejoin="round"/><polyline points="${pp}" fill="none" stroke="#7856bb" stroke-width="2.4" stroke-dasharray="5 4" stroke-linejoin="round"/>${dates.filter((_,i)=>(i%Math.max(1,Math.floor(dates.length/6))===0&&i<dates.length-1-Math.floor(dates.length/12))||i===dates.length-1).map(d=>`<text x="${x(dates.indexOf(d))}" y="232" text-anchor="middle" fill="#727080" font-size="9">${d.slice(5).replace('-','.')}</text>`).join('')}</svg>`}
function dashboard(a){const o=art(a.artifact),source=art(o.input),c=comp(a.comp);let history=C.normalize(source.rows,source.mapping);let output=o.rows;const series=[...new Set(history.map(r=>r.series_id))];if(seriesFilter!=='all'&&!series.includes(seriesFilter))seriesFilter='all';if(seriesFilter!=='all'){history=history.filter(r=>r.series_id===seriesFilter);output=output.filter(r=>r.series_id===seriesFilter)}const range=o.params.range;if(range!=='all')history=history.filter(r=>r.timestamp>=C.day(history.at(-1).timestamp,-Number(range)+1));const sum=output.reduce((v,r)=>v+r.forecast_value,0),horizon=Number(o.params.horizon),daily={};output.forEach(r=>daily[r.forecast_timestamp]=(daily[r.forecast_timestamp]||0)+r.forecast_value);const peak=Object.entries(daily).sort((a,b)=>b[1]-a[1])[0];return head('APP / DEMAND PLANNING',a.name,a.desc,btn('앱 설정','edit-app','settings')+`<a class="btn" href="#compositions/${c.id}">${icon('graph')}컴포지션</a>`+btn('결과 내보내기','download','download',false,`data-id="${o.id}"`))+`<div class="filterbar"><label>예측 기간<select data-app-param="horizon" aria-label="예측 기간">${options([[7,'다음 7일'],[14,'다음 14일'],[28,'다음 28일']],a.params.horizon)}</select></label><label>모델<select data-app-param="model" aria-label="예측 모델">${options([['seasonal','주간 반복 기준'],['last','직전 값 유지']],a.params.model)}</select></label><label>데이터 범위<select data-app-param="range" aria-label="학습 데이터 범위">${options([['all','전체 기간'],['28','최근 28일'],['56','최근 56일']],a.params.range)}</select></label><label>시계열<select id="series-filter" aria-label="시계열 필터">${options([['all','전체 메뉴'],...series.map(s=>[s,s])],seriesFilter)}</select></label><span class="auto">${busy?'<span class="spinner"></span> 새 결과 계산 중…':'<span class="dot"></span> 변경 시 자동 반영'}</span></div>${busy?'<div class="run-status running" role="status">새 설정으로 계산 중입니다. 아래에는 마지막으로 완료된 결과가 표시됩니다.</div>':''}${runError?`<div class="run-status error" role="alert">${esc(runError)}</div>`:''}<div class="metrics"><div class="metric"><div class="metric-label">예상 총수요 ${icon('chart')}</div><div class="metric-value">${fmt(sum)}<small>개</small></div><div class="metric-foot">${output[0]?.forecast_timestamp.slice(5)} — ${output.at(-1)?.forecast_timestamp.slice(5)} · ${horizon}일</div></div><div class="metric"><div class="metric-label">일평균 예상 수요</div><div class="metric-value">${fmt(Math.round(sum/horizon))}<small>개 / 일</small></div><div class="metric-foot">선택한 ${seriesFilter==='all'?series.length:1}개 시계열 합계 기준</div></div><div class="metric"><div class="metric-label">최대 수요 예상일</div><div class="metric-value">${peak[0].slice(5).replace('-','.')}<small>${new Date(peak[0]).toLocaleDateString('ko-KR',{weekday:'short'})}</small></div><div class="metric-foot positive">${fmt(peak[1])}개 예상</div></div><div class="metric"><div class="metric-label">분석한 관측값</div><div class="metric-value">${fmt(history.length)}<small>행</small></div><div class="metric-foot">${history[0].timestamp.slice(5)} — ${history.at(-1).timestamp.slice(5)} · 일 단위</div></div></div><section class="panel"><div class="panel-title"><div><h2>수요의 흐름</h2><span class="help">실제 판매와 앞으로의 예상 수요를 함께 살펴보세요.</span></div><div class="legend"><span><i></i>실제 판매</span><span><i class="dash"></i>예측 수요</span><span>단위: 개</span></div></div><div class="dashboard-chart">${chart(history,output)}</div></section><div class="dashboard-bottom"><section class="panel"><div class="panel-title"><h2>메뉴별 예상 수요</h2><span class="help">다음 ${horizon}일 합계</span></div><div class="panel-pad">${series.filter(s=>seriesFilter==='all'||s===seriesFilter).map(s=>{const total=output.filter(r=>r.series_id===s).reduce((v,r)=>v+r.forecast_value,0);return `<div class="product-row"><strong>${esc(s)}</strong><div class="bar"><i style="width:${sum?total/sum*100:0}%"></i></div><b>${fmt(total)}개</b></div>`}).join('')}<div class="help">예측 분포를 참고해 다음 발주를 계획해 보세요.</div></div></section><section class="panel"><div class="panel-title"><h2>이 결과가 만들어진 방법</h2>${badge('완료','green')}</div><div class="panel-pad"><dl class="metadata" style="margin-top:0;gap:13px"><div><dt>원본 데이터</dt><dd><a href="#artifacts/${source.id}">${esc(source.name)} ↗</a></dd></div><div><dt>적용 모델</dt><dd>${modelName(o.params.model)} · v1.0</dd></div><div><dt>실행 근거</dt><dd><a href="#runs/${o.run}">${o.run} · ${time(o.created)} ↗</a></dd></div></dl></div></section></div><div class="section-bar"><h2 class="section-title">예측 데이터</h2><a class="btn text" href="#artifacts/${o.id}">아티팩트 상세 보기 →</a></div><div class="panel">${table(output.map(r=>({'날짜':r.forecast_timestamp,'메뉴':r.series_id,'예측 수량':r.forecast_value,'모델':modelName(o.params.model)})),9)}</div><div class="scope-note">프로토타입 기준 예측입니다. ${o.params.model==='seasonal'?'변환된 시계열의 마지막 7일 수량을 요일별로 반복합니다.':'변환된 시계열의 마지막 관측값을 예측 기간 동안 유지합니다.'} 정확도 평가 및 신뢰 구간은 포함하지 않습니다.</div>`}
function entitiesPage(){return head('THE THINGS YOU WORK WITH','엔티티','데이터와 결과에 이름을 붙이고, 컴포지션에서 재사용하세요.',btn('엔티티 등록','new-entity','plus',true))+`<div class="info-strip">엔티티는 이름으로 참조하는 대상입니다. 실제 데이터는 연결된 아티팩트에 보관됩니다.</div><div class="toolbar"><h2 class="section-title">등록된 대상 <span class="muted">${state.entities.length}</span></h2>${searchbar()}</div><div class="catalog-list">${state.entities.filter(e=>e.name.includes(search)).map(e=>`<a class="card catalog-row" href="#entities/${e.id}"><span class="tile-icon green">${icon('entity')}</span><div><h3>${esc(e.name)}</h3><p>${e.kind} · ${e.artifacts.length}개 아티팩트</p></div><span class="arrow">↗</span></a>`).join('')}</div>`}
function entityDetail(e){return head('ENTITY / '+e.kind,e.name,e.desc,btn('엔티티 수정','edit-entity','settings',true))+`<div class="detail-grid"><section><div class="section-bar"><h2 class="section-title">연결된 아티팩트</h2></div><div class="cards" style="grid-template-columns:repeat(2,minmax(0,1fr))">${e.artifacts.map(id=>artifactCard(art(id))).join('')}</div></section><aside class="panel panel-pad"><h2 class="section-title">엔티티 정의</h2><dl class="metadata"><div><dt>Entity ID</dt><dd>${e.id}</dd></div><div><dt>Entity Kind</dt><dd>${e.kind}</dd></div><div><dt>스키마</dt><dd>${e.kind==='TimeSeriesTable'?'series_id: string<br>timestamp: date<br>value: number':'series_id: string<br>forecast_timestamp: date<br>forecast_value: number<br>model_version: string<br>run_id: string'}</dd></div></dl><p class="help">대상의 유형, 등록 대상, 실제 파일을 구분해 참조합니다.</p></aside></div>`}
function operationsPage(){return head('THE THINGS YOU CAN DO','오퍼레이션','입력을 읽고, 변환하고, 예측하는 재사용 가능한 기능입니다.')+`<div class="info-strip">오퍼레이션은 기능의 정의이고, 노드는 컴포지션 안에서 그 기능을 사용하는 자리입니다. 이 프로토타입에서는 아래 기능을 조합할 수 있습니다.</div><div class="toolbar"><h2 class="section-title">사용 가능한 기능 <span class="muted">${C.operations.length}</span></h2>${searchbar()}</div><div class="catalog-list">${C.operations.filter(o=>o.name.includes(search)).map(o=>`<a class="card catalog-row" href="#operations/${o.id}"><span class="tile-icon">${icon(o.icon)}</span><div><h3>${o.name}</h3><p>${o.desc}</p><span class="inline-code">${o.input} → ${o.output}</span></div><span class="arrow">↗</span></a>`).join('')}</div>`}
function operationDetail(o){const uses=state.compositions.filter(c=>c.nodes.includes(o.id));return head('OPERATION / v1.0',o.name,o.desc,btn('컴포지션에 추가','use-operation','plus',true,`data-id="${o.id}"`))+`<div class="detail-grid"><section class="panel panel-pad"><h2 class="section-title">입출력 계약</h2><div class="lineage"><span class="step">${o.input}</span><span>→</span><span class="step">${o.name}</span><span>→</span><span class="step">${o.output}</span></div><p class="help">${o.id==='forecast'?'예측 기간: 7 / 14 / 28일. 모델: 주간 반복 기준 또는 직전 값 유지. 범위: 전체 / 28 / 56일.':o.id==='normalize'?'유효한 날짜, 비어 있지 않은 시계열, 0 이상의 유한한 수량을 검증합니다. 중복 날짜와 누락된 날짜는 오류로 표시합니다.':o.desc}</p><div class="divider"></div><h2 class="section-title" style="margin-bottom:15px">이 기능을 쓰는 컴포지션</h2><div class="usage-list">${uses.map(c=>`<a href="#compositions/${c.id}">${esc(c.name)}<span>↗</span></a>`).join('')||'<p class="help">아직 사용하는 컴포지션이 없습니다.</p>'}</div></section><aside class="panel panel-pad"><dl class="metadata"><div><dt>등록 ID</dt><dd>${o.id}@1.0</dd></div><div><dt>실행 방식</dt><dd>로컬 데모 계산</dd></div><div><dt>효과</dt><dd>${o.id==='export'?'결과 아티팩트 생성':'입력에서 출력으로 변환'}</dd></div></dl></aside></div>`}
function runsTable(runs){return `<div class="panel">${runs.length?`<div class="table-scroll"><table><thead><tr><th>실행</th><th>컴포지션</th><th>설정</th><th>실행 시각</th><th>상태</th></tr></thead><tbody>${runs.map(r=>`<tr><td><a class="btn text" href="#runs/${r.id}">${r.id} ↗</a></td><td>${esc(comp(r.comp)?.name)} · v${r.version}</td><td>${modelName(r.params.model)} · ${r.params.horizon}일</td><td>${date(r.created)} ${time(r.created)}</td><td>${badge('완료','green')}</td></tr>`).join('')}</tbody></table></div>`:empty('아직 실행 이력이 없습니다','컴포지션을 실행하면 입력과 결과가 이곳에 기록됩니다.')}</div>`}
function runDetail(r){return head('RUN / EVIDENCE',r.id,`${comp(r.comp)?.name} · v${r.version} · ${date(r.created)} ${time(r.created)}`,`<a class="btn primary" href="#artifacts/${r.output}">결과 아티팩트 보기 →</a>`)+lineage(art(r.output))+`<div class="detail-grid"><section class="panel"><div class="panel-title"><h2>노드별 실행</h2>${badge('모두 완료','green')}</div>${r.nodes.map((id,i)=>`<div class="recent-row"><span class="tile-icon green">${icon('check')}</span><strong>${i+1}. ${C.operations.find(o=>o.id===id).name}</strong><span class="right">${badge('완료','green')}</span></div>`).join('')}</section><aside class="panel panel-pad"><h2 class="section-title">고정된 실행 설정</h2><dl class="metadata"><div><dt>모델</dt><dd>${modelName(r.params.model)} @1.0</dd></div><div><dt>기간</dt><dd>${r.params.horizon}일</dd></div><div><dt>데이터 범위</dt><dd>${r.params.range==='all'?'전체 기간':r.params.range+'일'}</dd></div><div><dt>입력 아티팩트</dt><dd><a href="#artifacts/${r.input}">${r.input} ↗</a></dd></div></dl></aside></div>`}
function render(){const {page,id}=route();let html;if(id){const item=page==='apps'?app(id):page==='compositions'?comp(id):page==='artifacts'?art(id):page==='entities'?state.entities.find(e=>e.id===id):page==='operations'?C.operations.find(o=>o.id===id):state.runs.find(r=>r.id===id);if(!item)html=empty('페이지를 찾을 수 없습니다','목록에서 다시 선택해 주세요.',`<a class="btn" href="#${page}">목록으로</a>`);else html=({apps:dashboard,compositions:compDetail,artifacts:artifactDetail,entities:entityDetail,operations:operationDetail,runs:runDetail}[page]||(()=>''))(item)}else html=({apps:appsPage,compositions:compsPage,artifacts:artifactsPage,entities:entitiesPage,operations:operationsPage,runs:()=>head('EVERY RUN, REMEMBERED','실행 이력','입력, 설정, 결과를 한 번의 실행으로 연결합니다.')+runsTable(state.runs)}[page]||appsPage)();shell(html)}
const dialog=document.querySelector('#dialog');let returnFocus=null;
function modal(title,body,submit,callback){returnFocus=document.activeElement;dialog.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2>${title}</h2><button class="close" type="button" data-action="close" aria-label="닫기">×</button></div><div class="dialog-body">${body}<div id="modal-error" class="error-text" role="alert"></div></div><div class="dialog-foot">${btn('취소','close','',false,'type="button"')}${submit?`<button class="btn primary" type="submit">${submit}</button>`:''}</div></form>`;if(!dialog.open)dialog.showModal();document.querySelector('#modal-form').onsubmit=async e=>{e.preventDefault();try{await callback(new FormData(e.target))}catch(error){document.querySelector('#modal-error').textContent=error.message}}}
function closeModal(){dialog.close();returnFocus?.focus()}
function download(a){const text=a.snapshot?JSON.stringify(a.snapshot,null,2):C.csv(a.rows);const blob=new Blob([text],{type:a.snapshot?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('파일 다운로드를 시작했습니다.')}
function nameValue(f,key='name'){const value=String(f.get(key)||'').trim();if(!value)throw Error('이름을 입력해 주세요.');return value}
function uploadModal(file){upload=null;modal('CSV를 아티팩트로 등록',`<p class="help">파일을 선택하고 날짜·시계열·수량 열을 연결하세요. 입력 아티팩트와 데이터셋 엔티티를 함께 만듭니다.</p><div class="upload-box">${icon('upload')}<strong>CSV 파일을 선택하세요</strong><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="CSV 파일 선택"><span class="help">최대 2MB · 일 단위 · 시계열당 연속 7일 이상</span></div><div class="actions" style="justify-content:center;margin:10px 0">${btn('가상 판매 데이터 사용','sample-upload','file',false,'type="button"')}</div><div id="upload-fields"></div>`,'아티팩트 등록',f=>{if(!upload)throw Error('CSV 파일을 선택해 주세요.');const entityName=nameValue(f);const mapping={timestamp:f.get('map-date'),series:f.get('map-series'),value:f.get('map-value')};C.normalize(upload.rows,mapping);const a={id:C.uid('artifact'),name:upload.name,kind:'input',rows:upload.rows,mapping,created:new Date().toISOString()};state.artifacts.unshift(a);state.entities.push({id:C.uid('entity'),name:entityName,desc:'CSV에서 등록한 일 단위 데이터셋',kind:'TimeSeriesTable',artifacts:[a.id]});save();closeModal();go('artifacts/'+a.id);toast('입력 아티팩트와 엔티티가 등록되었습니다.')});document.querySelector('#csv-file').onchange=e=>readUpload(e.target.files[0]);if(file)readUpload(file)}
async function readUpload(file){if(!file)return;try{if(file.size>2*1024*1024)throw Error('파일 크기가 2MB를 넘었습니다. 더 작은 CSV를 선택해 주세요.');const parsed=C.parseCSV(await file.text());setUpload({name:file.name,...parsed});document.querySelector('#modal-error').textContent=''}catch(e){upload=null;document.querySelector('#upload-fields').innerHTML='';document.querySelector('#modal-error').textContent=e.message}}
function setUpload(data){upload=data;const cols=data.headers.map(h=>[h,h]);const guess=(words,index)=>data.headers.find(h=>words.some(w=>h.toLowerCase().includes(w)))||data.headers[index]||data.headers[0];document.querySelector('#upload-fields').innerHTML=`<div class="info-strip">${esc(data.name)} · ${fmt(data.rows.length)}행 · ${data.headers.length}개 열</div>${field('데이터셋 엔티티 이름','name',data.name.replace(/\.csv$/i,''))}<div class="mapping-fields">${selectField('날짜 열','map-date',cols,guess(['date','time','날짜'],0))}${selectField('시계열 열','map-series',cols,guess(['product','series','sku','메뉴'],1))}${selectField('수량 열','map-value',cols,guess(['quantity','value','sales','수량'],2))}</div>${table(data.rows.slice(0,3))}`}
function newComp(input){modal('새 컴포지션',`${field('컴포지션 이름','name','새 수요 예측')}${selectField('입력 데이터','input',state.artifacts.filter(a=>a.kind==='input').map(a=>[a.id,a.name]),input||'input-demo')}<label class="choice"><input type="radio" name="template" value="forecast" checked><span><strong>수요 예측 템플릿</strong><small>CSV 읽기 → 정규화 → 예측 → 결과 CSV</small></span></label><label class="choice"><input type="radio" name="template" value="blank"><span><strong>빈 그래프에서 시작</strong><small>등록된 기능을 노드로 추가해 직접 구성합니다.</small></span></label>`,'컴포지션 만들기',f=>{const input=f.get('input');if(!art(input))throw Error('입력 아티팩트를 먼저 등록해 주세요.');const c={id:C.uid('comp'),name:nameValue(f),desc:'입력 데이터에서 예측 결과까지 연결하는 작업 흐름',input,nodes:f.get('template')==='forecast'?['read','normalize','forecast','export']:[],params:{horizon:14,model:'seasonal',range:'all'},version:0,published:false,dirty:true};state.compositions.unshift(c);save();closeModal();go('compositions/'+c.id);toast('컴포지션 초안이 만들어졌습니다. 발행하면 설계 아티팩트가 등록됩니다.')})}
function newApp(artifactId){const outputs=state.artifacts.filter(a=>a.kind==='output');modal('대시보드 앱 만들기',`${field('앱 이름','name','나의 수요 대시보드')}${selectField('연결할 결과 아티팩트','artifact',outputs.map(a=>[a.id,a.name+' · '+a.params.horizon+'일']),artifactId||outputs[0]?.id)}<div class="info-strip">선택한 결과와 그 결과를 만든 컴포지션을 연결합니다. 앱에서 기간·모델을 바꾸면 새 예측 결과를 생성합니다.</div>${outputs.length?'':'<p class="error-text">컴포지션을 먼저 실행해 예측 결과를 만들어 주세요.</p>'}`,'앱 만들기',f=>{const output=art(f.get('artifact'));if(!output)throw Error('연결할 예측 결과를 선택해 주세요.');const a={id:C.uid('app'),name:nameValue(f),desc:'데이터의 흐름을 살펴보고, 다음 결정을 준비하세요.',artifact:output.id,comp:output.comp,params:C.clone(output.params)};state.apps.unshift(a);save();closeModal();go('apps/'+a.id);toast('결과 아티팩트로 대시보드 앱이 만들어졌습니다.')})}
function entityModal(e){const all=state.artifacts.filter(a=>a.kind!=='composition');modal(e?'엔티티 수정':'엔티티 등록',`${field('엔티티 이름','name',e?.name||'새 데이터셋')}${field('설명','description',e?.desc||'이 데이터가 의미하는 대상을 설명하세요')}${e?'':selectField('연결할 아티팩트','artifact',all.map(a=>[a.id,a.name]),all[0]?.id)}`,'저장',f=>{if(e){e.name=nameValue(f);e.desc=f.get('description')}else{const a=art(f.get('artifact'));if(!a)throw Error('아티팩트를 선택해 주세요.');state.entities.push({id:C.uid('entity'),name:nameValue(f),desc:f.get('description'),kind:a.kind==='input'?'TimeSeriesTable':'ForecastTable',artifacts:[a.id]})}save();closeModal();render();toast('엔티티를 저장했습니다.')})}
function markDirty(c){c.dirty=true;runMessage='';runError='';save()}
function insertNode(c,id){let at=c.nodes.length;if(id==='smooth'){const f=c.nodes.indexOf('forecast');if(f!==-1)at=f}c.nodes.splice(at,0,id);selectedNode=at;markDirty(c)}
function addNodeModal(c){modal('오퍼레이션을 노드로 추가',`<p class="help">기능을 선택하면 그래프에 배치하고 인접 포트를 자동 연결합니다. 잘못된 순서는 실행 전에 알려드립니다.</p>${C.operations.map(o=>`<button type="button" class="op-choice" data-add-op="${o.id}"><span class="tile-icon">${icon(o.icon)}</span><span><strong>${o.name}</strong><small>${o.input} → ${o.output}</small></span></button>`).join('')}`,'',null);dialog.querySelectorAll('[data-add-op]').forEach(b=>b.onclick=()=>{insertNode(c,b.dataset.addOp);closeModal();render();toast('노드를 추가했습니다.')})}
function ensurePublished(c){if(!c.published||c.dirty)C.publish(state,c)}
async function runComp(c){if(busy)return;runError='';try{const errors=C.validate(c);if(errors.length)throw Error(errors.join('\n'));C.normalize(art(c.input).rows,art(c.input).mapping);ensurePublished(c);const snapshot=C.clone(c);busy=true;render();await new Promise(r=>setTimeout(r,850));const output=C.execute(state,snapshot,snapshot.params);runMessage=output.id;save();toast('예측 결과 CSV가 생성되었습니다.')}catch(e){runError=e.message;toast('입력 또는 연결을 확인해 주세요.')}finally{busy=false;render()}}
function updateApp(a,key,value){a.params[key]=key==='horizon'?Number(value):value;const generation=++appGeneration;clearTimeout(appTimer);busy=true;runError='';render();appTimer=setTimeout(()=>{if(generation!==appGeneration)return;try{const previous=art(a.artifact),oldRun=state.runs.find(r=>r.id===previous.run);const frozen={...C.clone(comp(a.comp)),input:oldRun.input,nodes:C.clone(oldRun.nodes),version:oldRun.version};const output=C.execute(state,frozen,C.clone(a.params));a.artifact=output.id;save();toast('새 설정으로 결과를 업데이트했습니다.')}catch(e){runError=e.message;a.params=C.clone(art(a.artifact).params)}finally{busy=false;render()}},700)}
function bindPage(){document.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;const position=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{currentFilter=b.dataset.filter;render()});document.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detailTab;render()});document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{selectedNode=Number(b.dataset.node);render()});const c=comp(route().id);document.querySelector('#comp-input')?.addEventListener('change',e=>{c.input=e.target.value;markDirty(c);render()});document.querySelectorAll('[data-param]').forEach(el=>el.onchange=e=>{c.params[el.name]=el.name==='horizon'?Number(el.value):el.value;markDirty(c);render()});document.querySelectorAll('[data-app-param]').forEach(el=>el.onchange=()=>updateApp(app(route().id),el.dataset.appParam,el.value));document.querySelector('#series-filter')?.addEventListener('change',e=>{seriesFilter=e.target.value;render()});const zone=document.querySelector('#dropzone');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files.length)uploadModal(e.dataTransfer.files[0])}}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,c=comp(route().id);try{switch(action){
case 'close':closeModal();break;
case 'guide':modal('화담 프로토타입 둘러보기',`<p class="help">Electron 데스크톱 앱의 정보 구조와 작업 흐름을 검증하는 HTML 프로토타입입니다.</p><ol class="help" style="line-height:2.5;padding-left:20px"><li><a href="#artifacts" data-action="close">아티팩트</a>에서 CSV를 업로드하거나 가상 데이터를 등록합니다.</li><li>컴포지션을 만들고 엔티티·오퍼레이션 노드를 연결합니다.</li><li>발행하면 설계 JSON이, 실행하면 예측 CSV가 등록됩니다.</li><li>결과에서 앱을 만들고 기간·모델·데이터 범위를 바꿔 보세요.</li><li>실행 이력에서 입력과 결과의 출처를 확인합니다.</li></ol><div class="info-strip">가상 데이터와 로컬 기준 계산을 사용합니다. AI 호출·Electron 백엔드·자유 배치 그래프 편집은 이 목업의 범위에 포함하지 않습니다. 그래프는 세로 순서로 자동 연결됩니다.</div><p class="help">변경 사항은 현재 브라우저에 저장됩니다. 다른 브라우저나 포트에서는 별도의 작업 공간으로 열립니다.</p>`,'',null);break;
case 'upload':uploadModal();break;
case 'sample-upload':{const rows=C.sampleRows();setUpload({name:'성수점_일별판매_샘플.csv',rows,headers:Object.keys(rows[0])});document.querySelector('#modal-error').textContent='';break}
case 'sample-download':download({name:'성수점_일별판매_샘플.csv',rows:C.sampleRows()});break;
case 'download':download(art(b.dataset.id));break;
case 'new-comp':newComp(b.dataset.input);break;
case 'new-app':newApp(b.dataset.artifact);break;
case 'new-entity':entityModal();break;
case 'edit-entity':entityModal(state.entities.find(e=>e.id===route().id));break;
case 'add-node':addNodeModal(c);break;
case 'node-remove':c.nodes.splice(selectedNode,1);selectedNode=-1;markDirty(c);render();break;
case 'node-up':case 'node-down':{const next=selectedNode+(action==='node-up'?-1:1);[c.nodes[selectedNode],c.nodes[next]]=[c.nodes[next],c.nodes[selectedNode]];selectedNode=next;markDirty(c);render();break}
case 'publish':C.publish(state,c);save();render();toast(`v${c.version} 발행 · 설계 아티팩트가 등록되었습니다.`);break;
case 'run':await runComp(c);break;
case 'edit-comp':modal('컴포지션 정보 수정',field('이름','name',c.name)+field('설명','desc',c.desc),'저장',f=>{c.name=nameValue(f);c.desc=f.get('desc');markDirty(c);closeModal();render()});break;
case 'save-meta':{const v=document.querySelector('#meta-name').value.trim();if(!v)throw Error('이름을 입력해 주세요.');c.name=v;markDirty(c);render();toast('이름을 저장했습니다.');break}
case 'edit-app':{const a=app(route().id);modal('앱 설정',field('앱 이름','name',a.name)+field('설명','desc',a.desc)+`<div class="info-strip">연결된 컴포지션: ${esc(comp(a.comp).name)}<br>현재 결과: ${a.artifact}</div>`,'저장',f=>{a.name=nameValue(f);a.desc=f.get('desc');save();closeModal();render();toast('앱 정보를 저장했습니다.')});break}
case 'use-operation':{const op=b.dataset.id;modal('기존 컴포지션에 노드 추가',selectField('컴포지션','comp',state.compositions.map(c=>[c.id,c.name]),state.compositions[0]?.id),'추가',f=>{const target=comp(f.get('comp'));if(!target)throw Error('컴포지션을 먼저 만들어 주세요.');insertNode(target,op);closeModal();go('compositions/'+target.id);toast('노드를 추가했습니다. 입력과 출력 연결을 확인해 주세요.')});break}
}}catch(error){runError=error.message;if(route().page==='compositions')render();toast(error.message)}});
window.addEventListener('hashchange',()=>{if(dialog.open)closeModal();currentFilter='all';search='';selectedNode=-1;detailTab='graph';runMessage='';runError='';seriesFilter='all';render();window.scrollTo(0,0)});
save();
render();
